{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED AS SELECT CAST(Adset_Name AS STRING) AS ADSET_NAME, CAST(Adset_ID AS STRING) AS ADSET_ID, CAST(ad_id AS STRING) AS AD_ID, CAST(ad_name AS STRING) AS AD_NAME, CAST(Account_Name AS STRING) AS ACCOUNT_NAME, CAST(Account_ID AS STRING) AS ACCOUNT_ID, CAST(Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(Campaign_ID AS STRING) AS CAMPAIGN_ID, COALESCE(cast(fc.product_id as string), cast(sh1.product_id as string), cast(sh2.product_id as string)) AS PRODUCT_ID, coalesce(cast(sh1.VARIANT_ID as string), cast(sh2.variant_id AS STRING)) AS VARIANT_ID, CAST(Date AS DATE) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', Date) AS DAY_OF_WEEK, EXTRACT(YEAR FROM Date) AS YEAR, EXTRACT(MONTH FROM Date) AS MONTH, CAST(Channel AS STRING) AS Channel, CAST(Account AS STRING) AS ACCOUNT, CAST(Clicks AS FLOAT64) AS CLICKS, CAST(Spend AS FLOAT64) AS SPEND, CAST(Impressions AS FLOAT64) AS IMPRESSIONS, CAST(Conversions AS FLOAT64) AS CONVERSIONS, CAST(Conversion_Value AS FLOAT64) AS CONVERSION_VALUE, coalesce(CAST(sh1.Product_Category AS STRING), cast(sh2.product_category as string)) AS PRODUCT_CATEGORY, coalesce(cast(sh1.sku as string), cast(sh2.sku as string)) AS sku FROM maplemonk.fytika_db_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category, SKU FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID ORDER BY Product_Category) = 1 ) sh1 ON fc.PRODUCT_ID = sh1.VARIANT_ID LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category, SKU FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID ORDER BY Product_Category) = 1 ) sh2 ON fc.PRODUCT_ID = sh2.PRODUCT_ID UNION ALL SELECT CAST(ADSET_NAME AS STRING), CAST(ADSET_ID AS STRING), CAST(AD_ID AS STRING), CAST(AD_NAME AS STRING), CAST(ACCOUNT_NAME AS STRING), CAST(ACCOUNT_ID AS STRING), CAST(CAMPAIGN_NAME AS STRING), CAST(CAMPAIGN_ID AS STRING), CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING), CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING), CAST(DATE AS DATE), CAST(AD_TYPE AS STRING), CAST(AD_STRENGTH AS STRING), CAST(AD_NETWORK_TYPE AS STRING), CAST(AD_FINAL_URL AS STRING), CAST(DAY_OF_WEEK AS STRING), CAST(YEAR AS INT64), CAST(MONTH AS INT64), CAST(Channel AS STRING), CAST(ACCOUNT AS STRING), CAST(clicks AS FLOAT64), CAST(spend AS FLOAT64), CAST(Impressions AS FLOAT64), CAST(Conversions AS FLOAT64), CAST(Conversion_Value AS FLOAT64), CAST(Product_Category AS STRING), cast(sc.sku as string) FROM maplemonk.Fytika_db_Product_GOOGLEADS_CONSOLIDATED gc LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category, SKU FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY PRODUCT_ID ORDER BY Product_Category) = 1 ) sc ON CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) = sc.PRODUCT_ID UNION ALL SELECT CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(AD_ID AS STRING), CAST(NAME AS STRING), CAST(NAME AS STRING), CAST(PROFILEID AS STRING), CAST(CAMPAIGNNAME AS STRING), CAST(CAMPAIGN_ID AS STRING), COALESCE(CAST(fc.ASIN AS STRING), CAST(sc.product_id AS STRING)) as product_id, CAST(sc.VARIANT_ID AS STRING), DATE(fc.Date), CAST(AD_TYPE_1 AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), FORMAT_DATE(\'%A\', DATE(fc.Date)) as day_of_week, EXTRACT(YEAR FROM DATE(fc.Date)) as year, EXTRACT(MONTH FROM DATE(fc.Date)) as month, \'Amazon\' as channel, CAST(NAME AS STRING) as account, SUM(CAST(clicks AS FLOAT64)), SUM(CAST(spend AS FLOAT64)), SUM(CAST(Impressions AS FLOAT64)), SUM(CAST(ATTRIBUTED_CONVERSIONS_14D AS FLOAT64)), SUM(CAST(ATTRIBUTED_SALES_14D AS FLOAT64)), CAST(category_name AS STRING) as category_name, CAST(sku_code AS STRING) as sku FROM maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED fc LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category, SKU FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID ORDER BY Product_Category) = 1 ) sc ON fc.sku_code = sc.sku GROUP BY AD_ID, NAME, PROFILEID, CAMPAIGNNAME, CAMPAIGN_ID, product_id, variant_id, DATE, AD_TYPE_1, DAY_OF_WEEK, YEAR, MONTH, Channel, ACCOUNT, sku_code, category_name UNION ALL SELECT CAST(Adset_Name AS STRING), CAST(Adset_ID AS STRING), CAST(ad_id AS STRING), CAST(ad_name AS STRING), CAST(Account_Name AS STRING), CAST(Account_ID AS STRING), CAST(Campaign_Name AS STRING), CAST(Campaign_ID AS STRING), CAST(product_id AS STRING), CAST(VARIANT_ID AS STRING), DATE, CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), FORMAT_DATE(\'%A\', Date), EXTRACT(YEAR FROM Date), EXTRACT(MONTH FROM Date), Channel, Account, CAST(Clicks AS FLOAT64), CAST(Spend AS FLOAT64), CAST(Impressions AS FLOAT64), CAST(Conversions AS FLOAT64), CAST(Conversion_Value AS FLOAT64), CAST(Product_Category AS STRING), cast(sku as string) FROM maplemonk.Fytika_db_Product_Flipkart_FSN;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            